<?php require_once __DIR__ . '/layout.php';
$month=$_GET['month']??date('Y-m'); $details=array_values(array_filter(request_rows(), fn($r)=>month_of($r['requested_at']??'')===$month));
$byUser=[]; $byReason=[]; foreach($details as $r){ $uk=$r['user_id']; if(!isset($byUser[$uk])) $byUser[$uk]=['full_name'=>$r['full_name'],'office'=>$r['office'],'total'=>0]; $byUser[$uk]['total']++; $rk=$r['reason_id']; if(!isset($byReason[$rk])) $byReason[$rk]=['name'=>$r['reason'],'total'=>0]; $byReason[$rk]['total']++; }
usort($byUser, fn($a,$b)=>$b['total']<=>$a['total'] ?: strcmp($a['full_name'],$b['full_name'])); usort($byReason, fn($a,$b)=>$b['total']<=>$a['total'] ?: strcmp($a['name'],$b['name'])); $topUsers=array_slice($byUser,0,10); $topReasons=array_slice($byReason,0,10); $total=count($details); usort($details, fn($a,$b)=>strcmp($a['full_name'],$b['full_name']) ?: strcmp($b['requested_at'],$a['requested_at'])); page_header('Statistics','stats'); ?>
<div class="card"><h2>Monthly statistics</h2><form class="filters" method="get"><div><label>Select month</label><input type="month" name="month" value="<?= h($month) ?>"></div><button class="btn">Generate</button></form></div><div class="grid"><div class="card"><div class="muted">Total requests for <?= h($month) ?></div><div class="stat"><?= $total ?></div></div><div class="card"><div class="muted">Most active user</div><div class="stat" style="font-size:22px"><?= h($topUsers[0]['full_name']??'—') ?></div></div><div class="card"><div class="muted">Most common reason</div><div class="stat" style="font-size:22px"><?= h($topReasons[0]['name']??'—') ?></div></div></div><div class="grid"><div class="card"><h3>Users with the most requests</h3><div class="chart-wrap"><canvas id="usersChart"></canvas></div><table><thead><tr><th>User</th><th>Office</th><th>Count</th></tr></thead><tbody><?php foreach($topUsers as $u): ?><tr><td><?= h($u['full_name']) ?></td><td><?= h($u['office']) ?></td><td><?= (int)$u['total'] ?></td></tr><?php endforeach; ?><?php if(!$topUsers): ?><tr><td colspan="3">No data.</td></tr><?php endif; ?></tbody></table></div><div class="card"><h3>Most common reasons</h3><div class="chart-wrap"><canvas id="reasonsChart"></canvas></div><table><thead><tr><th>Reason</th><th>Count</th></tr></thead><tbody><?php foreach($topReasons as $r): ?><tr><td><?= h($r['name']) ?></td><td><?= (int)$r['total'] ?></td></tr><?php endforeach; ?><?php if(!$topReasons): ?><tr><td colspan="2">No data.</td></tr><?php endif; ?></tbody></table></div></div><div class="card"><h3>All requests for the month</h3><table><thead><tr><th>User</th><th>Office</th><th>Date</th><th>Reason</th><th>Description</th><th>Status</th></tr></thead><tbody><?php foreach($details as $d): ?><tr><td><?= h($d['full_name']) ?></td><td><?= h($d['office']) ?></td><td><?= h(fmt_dt($d['requested_at'])) ?></td><td><?= h($d['reason']) ?></td><td><?= nl2br(h($d['description'])) ?></td><td><?= h($d['status']) ?></td></tr><?php endforeach; ?><?php if(!$details): ?><tr><td colspan="6">There are no requests for this month.</td></tr><?php endif; ?></tbody></table></div><script>window.addEventListener('load',function(){drawBarChart('usersChart',<?= json_encode(array_column($topUsers,'full_name'),JSON_UNESCAPED_UNICODE) ?>,<?= json_encode(array_map('intval',array_column($topUsers,'total'))) ?>);drawBarChart('reasonsChart',<?= json_encode(array_column($topReasons,'name'),JSON_UNESCAPED_UNICODE) ?>,<?= json_encode(array_map('intval',array_column($topReasons,'total'))) ?>);});</script><?php page_footer(); ?>
